    document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const id=a.getAttribute('href').slice(1);const el=document.getElementById(id);if(el){e.preventDefault();el.scrollIntoView({behavior:'smooth'});history.pushState(null,'','#'+id)}}));

    // FAQ accordion
    const faqs=Array.from(document.querySelectorAll('details.faq'));faqs.forEach(d=>d.addEventListener('toggle',()=>{if(d.open)faqs.filter(x=>x!==d).forEach(x=>x.open=false)}));

